/* Aubry & Vent — Caliber 08
   A dark, instrument-like page: warm metal on near-black, one accent the colour
   of brass, figures set in a monospace so they can be compared down a column. */

@import url('https://fonts.googleapis.com/css2?family=Spectral:ital,wght@0,300;0,400;0,500;1,300&family=Inter:wght@300;400;500&family=IBM+Plex+Mono:wght@400;500&display=swap');

:root {
  --ink: #07070a;
  --ink-2: #0d0e12;
  --ink-3: #14151a;
  --line: #262830;
  --line-soft: #1c1e25;
  --text: #e7e3da;
  --text-2: #a09a8e;
  --text-3: #6e6a62;
  --brass: #c39a5c;
  --brass-dim: #8a6c3e;
  --steel: #7f95a8;

  --serif: 'Spectral', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, 'Segoe UI', Helvetica, Arial, sans-serif;
  --mono: 'IBM Plex Mono', 'SFMono-Regular', Consolas, monospace;

  --gutter: clamp(1.25rem, 5vw, 5rem);
  --measure: 74rem;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 6rem;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--text);
  font-family: var(--sans);
  font-weight: 300;
  font-size: 16px;
  line-height: 1.62;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 400;
  letter-spacing: -0.012em;
  margin: 0;
}

p {
  margin: 0;
}

a {
  color: inherit;
}

::selection {
  background: var(--brass);
  color: var(--ink);
}

/* Faint machined grid over the whole page, so the black is never flat. */
.page {
  position: relative;
  min-height: 100vh;
  overflow-x: hidden;
}

.page::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(120% 70% at 70% -10%, rgba(195, 154, 92, 0.09), transparent 60%),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.016) 0 1px, transparent 1px 3px);
}

.page > * {
  position: relative;
  z-index: 1;
}

/* ---------- top bar ---------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 0.9rem var(--gutter);
  background: rgba(7, 7, 10, 0.82);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line-soft);
}

.wordmark {
  font-family: var(--serif);
  font-size: 1.05rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  white-space: nowrap;
}

.wordmark .amp {
  color: var(--brass);
  font-style: italic;
}

.topnav {
  display: flex;
  gap: 1.6rem;
  margin-left: auto;
  overflow-x: auto;
  scrollbar-width: none;
}

.topnav::-webkit-scrollbar {
  display: none;
}

.topnav a {
  position: relative;
  font-size: 0.74rem;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--text-3);
  text-decoration: none;
  white-space: nowrap;
  padding-bottom: 2px;
  transition: color 0.25s ease;
}

.topnav a::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -2px;
  height: 1px;
  width: 0;
  background: var(--brass);
  transition: width 0.3s ease;
}

.topnav a:hover {
  color: var(--text);
}

.topnav a.is-active {
  color: var(--text);
}

.topnav a.is-active::after {
  width: 100%;
}

.topcta {
  font-size: 0.74rem;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.55rem 1.1rem;
  border: 1px solid var(--line);
  color: var(--text-2);
  white-space: nowrap;
  transition: border-color 0.25s ease, color 0.25s ease, background 0.25s ease;
}

.topcta:hover {
  border-color: var(--brass-dim);
  color: var(--ink);
  background: var(--brass);
}

/* ---------- hero ---------- */

.hero {
  max-width: var(--measure);
  margin: 0 auto;
  padding: clamp(4rem, 11vh, 8.5rem) var(--gutter) clamp(4rem, 9vh, 7rem);
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: clamp(2rem, 6vw, 5rem);
  align-items: center;
}

.eyebrow {
  font-family: var(--mono);
  font-size: 0.7rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--brass);
  margin-bottom: 1.6rem;
}

.hero h1 {
  font-size: clamp(2.1rem, 4.6vw, 3.6rem);
  line-height: 1.12;
  max-width: 18ch;
  margin-bottom: 1.6rem;
}

.lede {
  font-size: clamp(1rem, 1.35vw, 1.12rem);
  color: var(--text-2);
  max-width: 46ch;
  line-height: 1.68;
}

.hero-figures {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin: 3rem 0 0;
  padding-top: 1.4rem;
  border-top: 1px solid var(--line-soft);
}

.hero-figures dt {
  font-size: 0.66rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-3);
  margin-bottom: 0.45rem;
}

.hero-figures dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 1.1rem;
  color: var(--text);
}

/* the plate: concentric rings and a slowly beating balance */
.hero-plate {
  display: grid;
  place-items: center;
  aspect-ratio: 1;
}

.plate-disc {
  position: relative;
  width: min(100%, 30rem);
  aspect-ratio: 1;
  border-radius: 50%;
  background:
    radial-gradient(circle at 34% 28%, rgba(255, 255, 255, 0.07), transparent 55%),
    conic-gradient(
      from 0deg,
      #16171c,
      #22242b,
      #15161b,
      #24262e,
      #14151a,
      #202229,
      #16171c
    );
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.05),
    0 40px 90px -40px rgba(0, 0, 0, 0.9);
}

.plate-disc::after {
  /* côtes de Genève, drawn as light stripes across the plate */
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: repeating-linear-gradient(
    112deg,
    rgba(255, 255, 255, 0.045) 0 1px,
    transparent 1px 9px
  );
  mix-blend-mode: screen;
}

.ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(195, 154, 92, 0.18);
}

.ring-a {
  inset: 7%;
}

.ring-b {
  inset: 20%;
  border-style: dashed;
  border-color: rgba(231, 227, 218, 0.09);
}

.ring-c {
  inset: 36%;
  border-color: rgba(195, 154, 92, 0.28);
}

.jewel {
  position: absolute;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #e08a7a, #7d1f2c);
  box-shadow: 0 0 12px rgba(224, 138, 122, 0.45);
}

.jewel-1 {
  top: 18%;
  left: 30%;
}

.jewel-2 {
  top: 62%;
  left: 22%;
}

.jewel-3 {
  top: 74%;
  left: 63%;
}

.balance-wheel {
  position: absolute;
  inset: 41%;
  border-radius: 50%;
  border: 2px solid rgba(231, 227, 218, 0.45);
  animation: beat 4s cubic-bezier(0.45, 0, 0.55, 1) infinite;
}

.balance-spoke {
  position: absolute;
  inset: 0;
  margin: auto;
  height: 1px;
  background: rgba(231, 227, 218, 0.35);
}

.balance-spoke.rot {
  transform: rotate(90deg);
}

@keyframes beat {
  0%,
  100% {
    transform: rotate(-125deg);
  }
  50% {
    transform: rotate(125deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .balance-wheel {
    animation: none;
  }
}

/* ---------- section shell ---------- */

.section {
  max-width: var(--measure);
  margin: 0 auto;
  padding: clamp(3.5rem, 8vh, 6.5rem) var(--gutter);
  border-top: 1px solid var(--line-soft);
}

.section-head {
  margin-bottom: clamp(2.25rem, 5vh, 3.5rem);
  max-width: 58ch;
}

.kicker {
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--brass);
  margin-bottom: 1rem;
}

.section h2 {
  font-size: clamp(1.6rem, 3vw, 2.3rem);
  line-height: 1.2;
}

.section-note {
  margin-top: 1rem;
  color: var(--text-2);
  max-width: 52ch;
}

/* ---------- power path ---------- */

.path {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line-soft);
}

.stage {
  position: relative;
  display: grid;
  grid-template-columns: 4.5rem minmax(0, 1fr) minmax(0, 17rem);
  gap: clamp(1rem, 3vw, 2.5rem);
  align-items: baseline;
  padding: 1.9rem 0;
  border-bottom: 1px solid var(--line-soft);
  transition: background 0.3s ease;
}

.stage::before {
  /* the rail the power travels down */
  content: '';
  position: absolute;
  left: 1.35rem;
  top: 0;
  bottom: 0;
  width: 1px;
  background: linear-gradient(180deg, var(--brass-dim), rgba(138, 108, 62, 0.25));
}

.stage:first-child::before {
  top: 50%;
}

.stage:last-child::before {
  bottom: 50%;
}

.stage:hover {
  background: linear-gradient(90deg, rgba(195, 154, 92, 0.055), transparent 65%);
}

.stage-num {
  position: relative;
  font-family: var(--mono);
  font-size: 0.78rem;
  color: var(--text-3);
  background: var(--ink);
  padding: 0.2rem 0;
  width: 2.7rem;
  text-align: center;
  transition: color 0.3s ease;
}

.stage:hover .stage-num {
  color: var(--brass);
}

.stage h3 {
  font-size: 1.3rem;
  margin-bottom: 0.4rem;
}

.stage-detail {
  color: var(--text-2);
  max-width: 54ch;
}

.stage-figure {
  font-family: var(--mono);
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--text);
  letter-spacing: 0.01em;
  border-left: 1px solid var(--line);
  padding-left: 1.1rem;
}

/* ---------- layers ---------- */

.layers {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0;
  border-top: 1px solid var(--line-soft);
}

.layer {
  display: grid;
  grid-template-columns: minmax(0, 20rem) minmax(0, 1fr);
  grid-template-areas:
    'head bar'
    'head note';
  column-gap: clamp(1.5rem, 4vw, 3rem);
  row-gap: 0.7rem;
  align-items: center;
  padding: 1.7rem 0;
  border-bottom: 1px solid var(--line-soft);
}

.layer-head {
  grid-area: head;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.layer h3 {
  font-size: 1.15rem;
}

.layer-thickness {
  font-family: var(--mono);
  font-size: 0.95rem;
  color: var(--brass);
}

.layer-bar {
  grid-area: bar;
  height: 14px;
  background: repeating-linear-gradient(
    90deg,
    var(--line-soft) 0 1px,
    transparent 1px 8px
  );
  align-self: end;
}

.layer-bar span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, rgba(195, 154, 92, 0.75), rgba(195, 154, 92, 0.2));
  border-left: 2px solid var(--brass);
}

.layer-note {
  grid-area: note;
  color: var(--text-2);
  align-self: start;
  max-width: 60ch;
}

/* ---------- specification ---------- */

.specs {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: clamp(2rem, 6vw, 5rem);
}

.spec-row {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--line-soft);
}

.spec-row dt {
  font-size: 0.78rem;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--text-3);
  white-space: nowrap;
}

.spec-row::after {
  content: '';
  flex: 1;
  height: 1px;
  background: repeating-linear-gradient(90deg, var(--line) 0 1px, transparent 1px 5px);
  order: 1;
}

.spec-row dd {
  order: 2;
  margin: 0;
  font-family: var(--mono);
  font-size: 0.92rem;
  color: var(--text);
  text-align: right;
  white-space: nowrap;
}

/* ---------- finishes ---------- */

.configs {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(17rem, 1fr));
  gap: 1px;
  background: var(--line-soft);
  border: 1px solid var(--line-soft);
}

.config {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1.9rem 1.6rem;
  background: var(--ink-2);
  transition: background 0.3s ease, box-shadow 0.3s ease;
}

.config:hover {
  background: var(--ink-3);
}

.config.is-chosen {
  background: var(--ink-3);
  box-shadow: inset 0 2px 0 var(--brass);
}

.config-top {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.config h3 {
  font-size: 1.25rem;
  line-height: 1.25;
}

.config-price {
  font-family: var(--mono);
  font-size: 1.4rem;
  color: var(--brass);
  letter-spacing: -0.01em;
}

.config-finish {
  color: var(--text-2);
  font-size: 0.95rem;
}

.config-lead,
.config-remaining {
  font-size: 0.82rem;
  letter-spacing: 0.06em;
  color: var(--text-3);
  text-transform: uppercase;
}

.config-remaining {
  margin-top: -0.4rem;
}

.config-remaining strong {
  font-family: var(--mono);
  font-weight: 500;
  color: var(--text);
}

.config-pick {
  margin-top: auto;
  padding-top: 1.4rem;
  background: none;
  border: 0;
  border-top: 1px solid var(--line-soft);
  color: var(--text);
  font: inherit;
  font-size: 0.76rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-align: left;
  cursor: pointer;
  transition: color 0.25s ease;
}

.config-pick:hover {
  color: var(--brass);
}

.config.is-chosen .config-pick {
  color: var(--brass);
}

/* ---------- workshop ---------- */

.atelier {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(19rem, 1fr));
  gap: 0;
  counter-reset: fact;
}

.atelier li {
  counter-increment: fact;
  position: relative;
  padding: 1.6rem 1.6rem 1.6rem 3.4rem;
  border-top: 1px solid var(--line-soft);
  color: var(--text-2);
  font-size: 1rem;
}

.atelier li::before {
  content: counter(fact, decimal-leading-zero);
  position: absolute;
  left: 0;
  top: 1.6rem;
  font-family: var(--mono);
  font-size: 0.72rem;
  color: var(--brass-dim);
}

/* ---------- reservation ---------- */

.reserve {
  padding-bottom: clamp(4.5rem, 10vh, 8rem);
}

.reserve-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.6rem clamp(1.5rem, 4vw, 3rem);
  max-width: 46rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.field-wide {
  grid-column: 1 / -1;
}

.reserve-form label {
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-3);
}

.reserve-form input,
.reserve-form select {
  font: inherit;
  font-size: 1rem;
  color: var(--text);
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--line);
  padding: 0.7rem 0;
  border-radius: 0;
  transition: border-color 0.25s ease;
}

.reserve-form select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-3) 50%),
    linear-gradient(135deg, var(--text-3) 50%, transparent 50%);
  background-position: right 8px center, right 3px center;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 1.6rem;
}

.reserve-form select option {
  background: var(--ink-2);
  color: var(--text);
}

.reserve-form input:focus,
.reserve-form select:focus {
  outline: none;
  border-bottom-color: var(--brass);
}

.field-submit {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.5rem;
  margin-top: 0.6rem;
}

.reserve-form button {
  font: inherit;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink);
  background: var(--brass);
  border: 1px solid var(--brass);
  padding: 0.95rem 2.1rem;
  cursor: pointer;
  transition: background 0.25s ease, color 0.25s ease;
}

.reserve-form button:hover {
  background: transparent;
  color: var(--brass);
}

.field-summary {
  font-family: var(--mono);
  font-size: 0.78rem;
  color: var(--text-3);
}

.confirmation {
  font-family: var(--serif);
  font-size: clamp(1.15rem, 2.1vw, 1.5rem);
  line-height: 1.5;
  color: var(--text);
  max-width: 48rem;
  padding: 2rem 2.2rem;
  background: var(--ink-2);
  border: 1px solid var(--line);
  border-left: 2px solid var(--brass);
}

/* ---------- footer ---------- */

.footer {
  max-width: var(--measure);
  margin: 0 auto;
  padding: 2.5rem var(--gutter) 3.5rem;
  border-top: 1px solid var(--line-soft);
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 2.5rem;
  align-items: baseline;
  font-size: 0.8rem;
  color: var(--text-3);
}

.footer-links {
  display: flex;
  gap: 1.5rem;
}

.footer-contact {
  margin-left: auto;
}

.footer-contact a {
  color: var(--text-2);
  text-decoration: none;
  border-bottom: 1px solid var(--line);
}

.footer-contact a:hover {
  color: var(--brass);
  border-bottom-color: var(--brass);
}

/* ---------- narrower ---------- */

@media (max-width: 900px) {
  .hero {
    grid-template-columns: 1fr;
    padding-top: 3.5rem;
  }
  .hero-plate {
    order: -1;
    aspect-ratio: auto;
  }
  .plate-disc {
    width: min(72%, 20rem);
  }
  .stage {
    grid-template-columns: 3.4rem minmax(0, 1fr);
    row-gap: 0.9rem;
  }
  .stage::before {
    left: 0.95rem;
  }
  .stage-num {
    width: 1.9rem;
    text-align: left;
  }
  .stage-figure {
    grid-column: 2;
  }
  .layer {
    grid-template-columns: 1fr;
    grid-template-areas: 'head' 'bar' 'note';
  }
  .specs {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .topbar {
    flex-wrap: wrap;
    gap: 0.75rem 1rem;
  }
  .topnav {
    order: 3;
    width: 100%;
    margin-left: 0;
    gap: 1.2rem;
  }
  .topcta {
    margin-left: auto;
  }
  .hero-figures {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.4rem 1rem;
  }
  .reserve-form {
    grid-template-columns: 1fr;
  }
  .footer-contact {
    margin-left: 0;
  }
}
